import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiError } from 'lib/api'
import { teamLogic } from 'scenes/teamLogic'

import { todaySeasonalChecklistRetrieve } from '../generated/api'
import type { SeasonalChecklistApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySeasonalCampaignLogicValues {
    currentTeamId: number | null // teamLogic
    campaign: SeasonalChecklistApi | null
    campaignLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySeasonalCampaignLogicActions {
    loadCampaign: () => any
    loadCampaignFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCampaignSuccess: (
        campaign: SeasonalChecklistApi | null,
        payload?: any
    ) => {
        campaign: SeasonalChecklistApi | null
        payload?: any
    }
}

export type todaySeasonalCampaignLogicType = MakeLogicType<
    todaySeasonalCampaignLogicValues,
    todaySeasonalCampaignLogicActions
>

export const todaySeasonalCampaignLogic = kea<todaySeasonalCampaignLogicType>([
    path(['products', 'today', 'seasonal', 'todaySeasonalCampaignLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        campaign: [
            null as SeasonalChecklistApi | null,
            {
                loadCampaign: async () => {
                    try {
                        return await todaySeasonalChecklistRetrieve(String(values.currentTeamId))
                    } catch (error) {
                        if (error instanceof ApiError && error.status === 404) {
                            return null
                        }
                        throw error
                    }
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadCampaign()
    }),
])
